//! Checks the port against rows recorded from the verbatim Wine C code
//! (`target/canon/glu32/harness.c`, built with ASan and UBSan). Generated by
//! `target/canon/glu32/gen_rows.py`. Each test is one C call, and results are
//! compared bit for bit.

use crate::geom::{
    edge_eval, edge_intersect, edge_sign, trans_eval, trans_leq, trans_sign, vert_ccw, vert_leq,
    Vertex,
};
use crate::mult_matrix_vec;
use crate::project::{invert_matrix, mult_matrices, project, unproject};

fn v(s: f64, t: f64) -> Vertex {
    Vertex { s, t }
}

fn assert_bits(got: f64, want: f64) {
    assert_eq!(got.to_bits(), want.to_bits());
}

fn assert_bits_all(got: &[f64], want: &[f64]) {
    assert_eq!(got.len(), want.len());
    for (g, w) in got.iter().zip(want) {
        assert_bits(*g, *w);
    }
}

/// Wine C: `__gl_vertLeq`.
#[test]
fn oracle_vert_leq_smaller_s() {
    let x0 = v(0.0, 5.0);
    let x1 = v(1.0, -3.0);
    assert!(vert_leq(&x0, &x1));
}

/// Wine C: `__gl_vertLeq`.
#[test]
fn oracle_vert_leq_equal_s_ordered_t() {
    let x0 = v(2.0, 1.0);
    let x1 = v(2.0, 4.0);
    assert!(vert_leq(&x0, &x1));
}

/// Wine C: `__gl_vertLeq`.
#[test]
fn oracle_vert_leq_equal_s_reversed_t() {
    let x0 = v(2.0, 4.0);
    let x1 = v(2.0, 1.0);
    assert!(!vert_leq(&x0, &x1));
}

/// Wine C: `TransLeq`.
#[test]
fn oracle_trans_leq_by_t() {
    let x0 = v(5.0, 0.0);
    let x1 = v(-1.0, 2.0);
    assert!(trans_leq(&x0, &x1));
}

/// Wine C: `__gl_vertCCW`.
#[test]
fn oracle_vert_ccw_counter_clockwise() {
    let x0 = v(0.0, 0.0);
    let x1 = v(1.0, 0.0);
    let x2 = v(0.0, 1.0);
    assert!(vert_ccw(&x0, &x1, &x2));
}

/// Wine C: `__gl_vertCCW`.
#[test]
fn oracle_vert_ccw_clockwise() {
    let x0 = v(0.0, 0.0);
    let x1 = v(0.0, 1.0);
    let x2 = v(1.0, 0.0);
    assert!(!vert_ccw(&x0, &x1, &x2));
}

/// Wine C: `__gl_edgeEval`.
#[test]
fn oracle_edge_eval_left_gap_smaller() {
    let x0 = v(0.0, 0.0);
    let x1 = v(1.0, 3.0);
    let x2 = v(4.0, -2.0);
    assert_bits(edge_eval(&x0, &x1, &x2), 3.5);
}

